begin;
create temporary table payee_tag_results(name text,passed boolean);
do $$
declare actor uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();tag uuid;p uuid;q uuid;a uuid;tx uuid;r jsonb;before_row jsonb;rev integer;
begin
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values(actor,'mock-tags-'||actor||'@example.invalid',now(),false);
insert into household_private.memberships(user_id,status,role)values(actor,'approved','member');
insert into auth.sessions(id,user_id,aal)values(sid,actor,'aal1');
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at)values(gen_random_uuid(),sid,'passkey',now(),now());
perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
tag:=(public.household_v1('create_payee_tag',jsonb_build_object('name','Mock family '||actor))->>'id')::uuid;
if not exists(select 1 from jsonb_array_elements(public.household_v1('list_payee_tags'))v where v->>'id'=tag::text and v->>'payee_count'='0')then raise exception 'Tag catalog read failed';end if;
p:=(public.household_v1('create_payee',jsonb_build_object('name','Mock tagged '||actor,'kind','person','tag_ids',jsonb_build_array(tag)))->>'id')::uuid;
q:=(public.household_v1('create_payee',jsonb_build_object('name','Mock second '||actor,'kind','business'))->>'id')::uuid;
insert into household_private.accounts(name,kind,currency)values('Mock tags bank','checking','CAD')returning id into a;
insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint,payee_id,source_data)values(a,'2026-10-01','Mock source',-123,'mock-tags-'||actor,p,'{"tags":["Original"]}')returning id into tx;
select to_jsonb(t)into before_row from household_private.transactions t where id=tx;
select value into r from jsonb_array_elements(public.household_v1('list_payees'))where value->>'id'=p::text;
if jsonb_array_length(r->'tags')<>1 or r->>'transaction_count'<>'1' or r->>'last_transaction'<>'2026-10-01'then raise exception 'Directory metadata missing';end if;
if not exists(select 1 from jsonb_array_elements(public.household_v1('list_payee_tags'))v where v->>'id'=tag::text and v->>'payee_count'='1')then raise exception 'Tag usage count failed';end if;
perform public.household_v1('update_payee_tag',jsonb_build_object('id',tag,'revision',1,'name','Mock renamed '||actor,'archived',true));
if not exists(select 1 from household_private.payee_tag_links where payee_id=p and tag_id=tag)then raise exception 'Rename/archive lost links';end if;
begin perform public.household_v1('bulk_payee_tag',jsonb_build_object('tag_id',tag,'action','add','payees',jsonb_build_array(jsonb_build_object('id',q,'revision',1))));raise exception 'Archived tag assigned';exception when invalid_parameter_value then null;end;
perform public.household_v1('update_payee_tag',jsonb_build_object('id',tag,'revision',2,'name','Mock renamed '||actor,'archived',false));
begin perform public.household_v1('bulk_payee_tag',jsonb_build_object('tag_id',tag,'action','add','payees',jsonb_build_array(jsonb_build_object('id',q,'revision',1),jsonb_build_object('id',p,'revision',999))));raise exception 'Stale bulk accepted';exception when serialization_failure then null;end;
if exists(select 1 from household_private.payee_tag_links where payee_id=q)then raise exception 'Partial bulk commit';end if;
perform public.household_v1('bulk_payee_tag',jsonb_build_object('tag_id',tag,'action','add','payees',jsonb_build_array(jsonb_build_object('id',q,'revision',1))));
perform public.household_v1('bulk_payee_tag',jsonb_build_object('tag_id',tag,'action','remove','payees',jsonb_build_array(jsonb_build_object('id',q,'revision',2))));
if exists(select 1 from household_private.payee_tag_links where payee_id=q)then raise exception 'Remove failed';end if;
perform public.household_v1('update_payee',jsonb_build_object('id',p,'revision',1,'name','Mock tagged '||actor,'kind','person','aliases','[]'::jsonb,'tag_ids','[]'::jsonb));
if exists(select 1 from household_private.payee_tag_links where payee_id=p)then raise exception 'Editor tag clear failed';end if;
if (select to_jsonb(t)from household_private.transactions t where id=tx)is distinct from before_row then raise exception 'Payee tags changed ledger';end if;
begin perform public.household_v1('create_payee_tag',jsonb_build_object('name',' MOCK RENAMED '||upper(actor::text)));raise exception 'Duplicate name accepted';exception when invalid_parameter_value then null;end;
insert into payee_tag_results values('editable tags, rename/archive/restore, directory activity, atomic stale bulk and ledger preservation',true);
if has_table_privilege('authenticated','household_private.payee_tags','select')or has_table_privilege('authenticated','household_private.payee_tag_links','insert')or has_function_privilege('authenticated','household_private.payee_tag_action(text,jsonb)','execute')then raise exception 'Private access leaked';end if;
update auth.mfa_amr_claims set authentication_method='otp'where session_id=sid;
begin perform public.household_v1('list_payee_tags');raise exception 'OTP tags access';exception when insufficient_privilege then null;end;
insert into payee_tag_results values('private table/helper privileges and live passkey gate',true);
end $$;
select * from payee_tag_results;
rollback;
